import numpy as np
import torch
from sklearn.metrics import accuracy_score, f1_score, confusion_matrix
from dataset.solvers import solve_tokenized
import matplotlib.pyplot as plt
import matplotlib.lines as mlines

def map_facts_to_tokens(input_ids_list, final_facts):
    labels = torch.zeros(len(input_ids_list), dtype=torch.long)
    for i, token_id in enumerate(input_ids_list):
        if token_id in final_facts:
            labels[i] = 1
    return labels


def extract_data(llm_model, ds, initial_embeddings, hidden_states, layer_idx=-1, as_tensor=False):
    device = next(llm_model.parameters()).device
    X_list, y_list = [], []
    llm_model.eval()
    with torch.no_grad():
        for i in range(len(ds)):
            input_ids = torch.tensor(ds[i]["input_ids"], device=device).unsqueeze(0)
            type_ids = torch.tensor(ds[i]["type_embeddings"], device=device).unsqueeze(0)
            initial_embeddings.clear()
            hidden_states.clear()

            _ = llm_model.forward(input_ids=input_ids, type_embeddings=type_ids, start_pos=0)

            final_state = hidden_states[layer_idx].squeeze(0).to(device)  # (seq_len, dim)
            final_facts = solve_tokenized(input_ids, type_ids, layer_by_layer=False)
            token_labels = map_facts_to_tokens(ds[i]["input_ids"], final_facts)
            if as_tensor:
                X_list.append(final_state)
                y_list.append(token_labels)
            else:
                X_list.append(final_state.cpu().numpy())
                y_list.append(token_labels.cpu().numpy())
    if as_tensor:
        return torch.cat(X_list, dim=0), torch.cat(y_list, dim=0)
    else:
        return np.concatenate(X_list, axis=0), np.concatenate(y_list, axis=0)


def print_formatted_cm(y_true, y_pred, split_name):
    cm = confusion_matrix(y_true, y_pred)
    tn, fp, fn, tp = cm.ravel()
    print(f"\n--- {split_name} results ---")
    print(f"Accuracy: {accuracy_score(y_true, y_pred):.4f}")
    print(f"F1 score (Macro): {f1_score(y_true, y_pred, average='macro'):.4f}")
    print("\nConfusion Matrix:")
    print(f"{'':<22} | {'Pred unprovable (0)':<20} | {'Pred provable (1)':<20} |")
    print(f"-" * 69)
    print(f"{'Actual unprovable (0)':<22} | {tn:<20} | {fp:<20} | (False positives)")
    print(f"{'Actual provable (1)':<22} | {fn:<20} | {tp:<20} | (True positives)")


def train_probe(llm_model, probe, train_ds, initial_embeddings, hidden_states, tensor=False):
    X_train, y_train = extract_data(llm_model, train_ds, initial_embeddings, hidden_states, as_tensor=tensor)
    print(f"\nTraining probe on {X_train.shape[0]} tokens with dimension {X_train.shape[1]}...")
    probe.fit(X_train, y_train)
    train_preds = probe.predict(X_train)
    if tensor:
        y_train = y_train.cpu().numpy()
        train_preds = train_preds.cpu().numpy()
    print_formatted_cm(y_train, train_preds, "Training")


def extract_and_eval_probe(llm_model, probe, ds, initial_embeddings, hidden_states, layer_idx=None):
    device = next(llm_model.parameters()).device
    llm_model.eval()
    num_layers = len(llm_model.layers)
    target_layers = list(range(num_layers + 1)) if layer_idx is None else [layer_idx]

    all_y_true = []
    all_y_pred = {l: [] for l in target_layers}
    with torch.no_grad():
        for i in range(len(ds)):
            input_ids = torch.tensor(ds[i]["input_ids"], device=device).unsqueeze(0)
            type_ids = torch.tensor(ds[i]["type_embeddings"], device=device).unsqueeze(0)
            initial_embeddings.clear()
            hidden_states.clear()

            _ = llm_model.forward(input_ids=input_ids, type_embeddings=type_ids, start_pos=0)

            final_facts = solve_tokenized(input_ids, type_ids, layer_by_layer=False)
            token_labels = map_facts_to_tokens(ds[i]["input_ids"], final_facts).cpu().numpy()
            all_y_true.append(token_labels)
            all_layers = [initial_embeddings[0]] + hidden_states
            for l in target_layers:
                state = all_layers[l].squeeze(0).to(device)
                logits = probe.forward(state, layer_idx=l)
                preds = torch.argmax(logits, dim=-1).cpu().numpy()
                all_y_pred[l].append(preds)

    y_true_cat = np.concatenate(all_y_true, axis=0)
    results = {}
    for l in target_layers:
        y_pred_cat = np.concatenate(all_y_pred[l], axis=0)
        acc = accuracy_score(y_true_cat, y_pred_cat)
        f1 = f1_score(y_true_cat, y_pred_cat, average='macro')
        results[l] = {'accuracy': acc, 'f1': f1}
    return results

