def plot_provability_probe_evolution(aggregated_results, dataset_order, alignment_order, style_labels, variation_idx, y_min=0.25, save_filename=None):
    plt.style.use('seaborn-v0_8-whitegrid')
    plt.rcParams['pdf.fonttype'] = 42
    plt.rcParams['ps.fonttype'] = 42
    fig, ax = plt.subplots(figsize=(4, 4))
    raw_models = list(set([key[0] for key in aggregated_results.keys()]))

    def sort_key(model_label):
        import re
        match = re.search(r'L = (\d+)', model_label)
        return (int(match.group().split(" = ")[1]) if match else 0) * 100 - len(model_label)

    unique_models = sorted(raw_models, key=sort_key)
    colors = ['black', 'navy', 'tab:purple', 'tab:cyan', 'tab:blue']
    model_color_map = {model: colors[i % len(colors)] for i, model in enumerate(unique_models)}
    legend_handles_models = {}
    style_keys = dataset_order if variation_idx == 1 else alignment_order
    anchors = [0, 8, 16, 32, 64, 128, 256, 512, 1024]
    mapped_anchors = list(range(len(anchors)))

    def map_layer_to_x(layer):
        return np.interp(layer, anchors, mapped_anchors)

    max_plotted_layer = 0
    for key, metrics in aggregated_results.items():
        model_name, dataset_name, is_aligned = key
        if dataset_name not in dataset_order or is_aligned not in alignment_order:
            continue

        layers = sorted(metrics.keys())
        if layers:
            max_plotted_layer = max(max_plotted_layer, max(layers))
        f1_scores = [metrics[l]['f1'] for l in layers]
        mapped_layers = [map_layer_to_x(l) for l in layers]
        variation_val = key[variation_idx]
        style_idx = style_keys.index(variation_val)
        line_style = '-' if style_idx == 0 else '--'
        marker = 'o' if style_idx == 0 else 'x'
        c = model_color_map[model_name]
        ax.plot(mapped_layers, f1_scores, color=c, linestyle=line_style, marker=marker, markersize=2, alpha=0.8, linewidth=1)
        if model_name not in legend_handles_models:
            legend_handles_models[model_name] = mlines.Line2D([], [], color=c, marker='s', linestyle='None', label=model_name)

    needed_anchor_count = sum(1 for a in anchors if a <= max_plotted_layer)
    if max_plotted_layer not in anchors:
        needed_anchor_count += 1
    display_anchors = map(str, anchors[:needed_anchor_count])
    display_mapped = mapped_anchors[:needed_anchor_count]
    ax.set_xticks(display_mapped)
    ax.set_xticklabels(display_anchors)

    handles_models = [legend_handles_models[m] for m in unique_models if m in legend_handles_models]
    handles_styles = [
        mlines.Line2D([], [], color='gray', linestyle='-', marker='o', label=style_labels[0]),
        mlines.Line2D([], [], color='gray', linestyle='--', marker='x', label=style_labels[1])
    ]
    max_len = max(len(handles_models), len(handles_styles))
    dummy = mlines.Line2D([], [], color='none', marker='none', linestyle='none', label=' ')
    padded_models = handles_models + [dummy] * (max_len - len(handles_models))
    padded_styles = handles_styles + [dummy] * (max_len - len(handles_styles))
    final_handles = padded_models + padded_styles

    ax.set_xlabel("Transformer layer index", fontsize=12)
    ax.set_ylabel("Probe F1 score", fontsize=12)
    ax.grid(True, alpha=0.3)
    ax.set_ylim(y_min, 1.05)
    ax.legend(handles=final_handles, loc='upper left', ncol=2, fontsize=9, columnspacing=0.5)

    plt.tight_layout()
    if save_filename:
        plt.savefig(save_filename, bbox_inches='tight')
    plt.show()

def plot_provability_cached():
    plot_provability_probe_evolution(
        aggregated_results=scaling_aggregated_results,
        dataset_order=['validation_lp_balanced_deep_30_pred', 'validation_lp_balanced_deep_60_pred'],
        alignment_order=[True],
        variation_idx=1,
        style_labels=(r'$N_{pred} \leq 30$', r'$N_{pred} \leq 60$'),
        y_min=0.25,
        save_filename="provability_probe_lp.pdf"
    )
